use vstd::prelude::*;

verus! {

spec fn all_ones(s: Seq<i32>) -> bool {
    forall|j: int| 0 <= j < s.len() ==> s[j] == 1
}

fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
    ensures
        result@.len() == a@.len(),
        all_ones(result@),
{
    let n = a.len();
    let mut result: Vec<i32> = Vec::with_capacity(n);

    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            result@.len() == i as int,
            all_ones(result@),
        decreases n - i,
    {
        // After i iterations, result.len() == i and all elements so far are 1.
        result.push(1);
        i += 1;
    }

    result
}

} // verus!

